def solve_n4():
    # Iterate through small positive integers for x1 and x2
    max_x = 10

    for x1 in range(1, max_x + 1):
        for x2 in range(1, max_x + 1):
            # Step 1: Find integer x3
            numerator_x3 = x2**2 + 1
            denominator_x3 = x1 + 1

            if numerator_x3 % denominator_x3 == 0:
                x3_plus_1 = numerator_x3 // denominator_x3
                x3 = x3_plus_1 - 1

                if x3 >= 1:
                    # Step 2: Find integer x4
                    numerator_x4 = x3**2 + 1
                    denominator_x4 = x2 + 1

                    if numerator_x4 % denominator_x4 == 0:
                        x4_plus_1 = numerator_x4 // denominator_x4
                        x4 = x4_plus_1 - 1

                        if x4 >= 1:
                            print(f"Solution found for n=4: x1={x1}, x2={x2}, x3={x3}, x4={x4}")
                            return True
    return False

solve_n4()
